    T('IP Address 192.168.1.10 อยู่ในคลาสใด (ตอบตัวอักษร)',['c','classc','คลาสc'],'ไบต์แรก 192–223','ไบต์แรก 192 จึงเป็น Class C'),
    T('Subnet Mask เริ่มต้นของ Class B คืออะไร',['255.255.0.0'],'Class B ใช้ 2 ไบต์แรกเป็น Network','Class A = 255.0.0.0, B = 255.255.0.0, C = 255.255.255.0'),
    C('มาตรฐาน IEEE 802.11 คือเครือข่ายแบบใด',['เครือข่ายไร้สาย Wi-Fi','เครือข่ายแบบใช้สาย Ethernet','เครือข่ายวงแหวน Token Ring','เครือข่ายส่วนบุคคล Bluetooth'],0,'802.3 คือ Ethernet','IEEE 802.11 เป็นมาตรฐาน Wireless LAN')
