WEEKS.forEach((w,i)=>{
  w.color=PIN[i%8];
  w.ref=`หน่วยที่ ${w.unit} สัปดาห์ที่ ${w.week} (หนังสือเล่ม 1 บทที่ ${w.unit})`;
  w.blurb=w.intro[0];
  w.label='สัปดาห์ที่ '+w.week;
  w.exit=true;
});
const WVM={w11:'w11',w12:'r9',w14:'r10',w16:'r11',w18:'r12'};
WEEKS.forEach(w=>{ if(WVM[w.id]){ const v=VMX[WVM[w.id]]; w.vmSetup=v.setup; w.vmTasks=v.tasks; } });
WEEKS.forEach(w=>{ w.minutes = w.vmTasks?25 : w.terminal?20 : 15; });
ROOMS.forEach((r,i)=>{ r.label='ห้อง '+(i+1); });
const ALL=ROOMS.concat(WEEKS);
module.exports={ROOMS,WEEKS,ALL,VMX};
